def parse_ports(lines):
    ports = []
    for line in lines:
        parts = line.split()
        if len(parts) >= 2:
            protocol = parts[0]
            port_str = parts[1]
            if protocol == 'tcp' and port_str == 'open':
                try:
                    port = int(port_str)
                    ports.append(port)
                except ValueError:
                    pass
    return sorted(set(ports))
